import{_ as t,o,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Contracts — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Contracts — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/contracts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Contracts — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/contracts"}]]},"headers":[],"relativePath":"deployment/contracts.md","filePath":"deployment/contracts.md","lastUpdated":1787227217000}'),a={name:"deployment/contracts.md"};function c(r,e,s,l,d,p){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="contracts-—-production-guide" tabindex="-1">Contracts — Production Guide <a class="header-anchor" href="#contracts-—-production-guide" aria-label="Permalink to &quot;Contracts — Production Guide&quot;">​</a></h1><p>Full go-live audit / checklist: <a href="./contracts-production-readiness">Contracts 1.1.0 production readiness</a>.</p><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>contracts</code></li><li>Category: <strong>Sales</strong> (<code>sales</code>)</li><li><strong>Free Marketplace opt-in</strong> (not auto-installed)</li><li>Catalog flags: <code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code>, <code>sort_order = 60</code>, version <strong>1.2.0</strong></li><li><strong>Hard dependency</strong>: requires the <strong>Opportunities</strong> module — install is blocked at the Marketplace/API level until Opportunities is entitled</li><li><strong>Soft optional dependency</strong>: linking a <code>quotation_id</code> requires the <strong>Quotations</strong> module to also be entitled; the link is otherwise rejected by validation (<code>LinkableQuotation</code>)</li><li>Existing workspaces that already have Contracts keep their subscription (policy change does not uninstall)</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create:</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules only (Contracts is never auto-installed)</li><li>Operators enable Opportunities first, then Contracts, from Marketplace (free / non-billable install activates immediately)</li><li>Tenant permissions include <code>contracts.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li></ol><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Contracts permissions for <strong>existing</strong> workspaces ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code>. Do <strong>not</strong> re-seed roles.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>contract_created</code>, <code>contract_updated</code>, <code>contract_deleted</code>, <code>contract_assigned</code>, <code>contract_status_changed</code>, <code>contract_invoice_created</code>, <code>contract_note_added</code></li><li>Notifications: assignment via <code>ContractAssignedNotification</code></li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate tables (<code>contracts</code>, <code>contract_notes</code>, <code>contract_activities</code>) plus <code>description</code> (1.1.0), <code>customer_invoices.contract_id</code> (1.2.0), convert permission, and catalog bump through <strong>1.2.0</strong></li><li>Register the <code>contracts</code> catalog module via migration (<code>DefaultModuleRegistrar</code>) as free Sales opt-in — <strong>not</strong> <code>db:seed</code></li><li>Register the hard dependency row (<code>contracts</code> → <code>opportunities</code>) via migration</li><li>Run contracts permissions migration so default roles receive missing <code>contracts.*</code> grants</li><li>Confirm <code>module:contracts</code> + <code>contracts.*</code> permissions on target roles</li><li>Deploy Frontend SPA with Contracts nav/pages (mirror Opportunities/Quotations table + form) when the SPA ships</li></ol>',13)])])}const m=t(a,[["render",c]]);export{g as __pageData,m as default};
